// Generated by OSL (@osl/backend-hono-trpc-vite). Sign-in providers beyond passwords (magic links, OAuth) and invites. Transport-neutral; the auth routes set the cookie.
// Do not edit: this file is rewritten on every osl generate.

import { createHash, randomBytes } from "node:crypto";
import { and, eq, gt } from "drizzle-orm";
import { db } from "./db/client";
import { users as identityTable, oslAuthTokens, oslAuthStates, oslAuthAccounts, articleInvites, articleEditors, articles, type ArticleInvite, type NewArticleInvite, type User } from "./db/schema";
import { fail } from "./server/errors";
import { emailMode, inviteEmail, sendEmail } from "./email";
import type { Session } from "./server/auth";

/** Where the web app lives: magic links and invites point here and OAuth returns here (OSL_APP_URL) */
export const APP_URL = (process.env.OSL_APP_URL ?? "http://localhost:3000").replace(/\/$/, "");

const MAGIC_LINK_MINUTES = 10;
const OAUTH_STATE_MINUTES = 10;

export const PROVIDERS: { kind: string; name: string }[] = [
  { kind: "credentials", name: "credentials" },
  { kind: "magic_link", name: "magic_link" },
  { kind: "oauth", name: "github" }
];

function hash(value: string): string {
  return createHash("sha256").update(value).digest("base64url");
}

/** The user with this email, created when the identity needs nothing but an email and a name. */
export async function findOrCreateByEmail(rawEmail: string, name?: string): Promise<User> {
  const email = rawEmail.trim().toLowerCase();
  const existing = await db.query.users.findFirst({ where: eq(identityTable.email, email) });
  if (existing) return existing;
  const [created] = await db
    .insert(identityTable)
    .values({ email: email, name: name ?? email.split("@")[0] })
    .returning();
  return created;
}

/**
 * Email a one-time sign-in link. Answers the token only when emails are captured (tests); otherwise null, and the
 * caller always reports success so addresses cannot be probed.
 */
export async function issueMagicLink(rawEmail: string): Promise<{ token: string; url: string } | null> {
  const email = rawEmail.trim().toLowerCase();
  const user = await db.query.users.findFirst({ where: eq(identityTable.email, email) });
  if (!user && !true) return null;
  const token = randomBytes(32).toString("base64url");
  await db.insert(oslAuthTokens).values({
    token_hash: hash(token),
    email,
    purpose: "magic_link",
    expires_at: new Date(Date.now() + MAGIC_LINK_MINUTES * 60_000)
  });
  const url = APP_URL + "/login/verify?token=" + encodeURIComponent(token);
  await sendEmail({
    to: email,
    subject: "Your sign-in link",
    text: "Sign in with this link (valid for " + MAGIC_LINK_MINUTES + " minutes): " + url
  });
  return emailMode() === "capture" ? { token, url } : null;
}

/**
 * Take the token (once) and answer its user, creating the user when the model allows. The link has proven the
 * address, so the invites waiting for it are accepted.
 */
export async function verifyMagicLink(token: string): Promise<{ user: User; accepted: Accepted[] }> {
  const [row] = await db.delete(oslAuthTokens).where(eq(oslAuthTokens.token_hash, hash(token))).returning();
  if (!row || row.purpose !== "magic_link" || row.expires_at.getTime() < Date.now()) fail(400, "invalid_token", "This link is invalid or has expired");
  const user = await findOrCreateByEmail(row.email);
  return { user, accepted: await acceptPending(user, row.email) };
}

type ProviderConfig = (
  | { kind: "github"; authorize: string; token: string; scope: string; pkce: false }
  | { kind: "oidc"; issuer: string; scope: string; pkce: true }
) & { clientId: string; clientSecret: string };

export const OAUTH: Record<string, ProviderConfig> = {
  "github": { ...{ kind: "github", authorize: "https://github.com/login/oauth/authorize", token: "https://github.com/login/oauth/access_token", scope: "read:user user:email", pkce: false }, clientId: process.env.OAUTH_GITHUB_CLIENT_ID ?? "", clientSecret: process.env.OAUTH_GITHUB_CLIENT_SECRET ?? "" }
};

const discovered = new Map<string, Promise<{ authorization_endpoint: string; token_endpoint: string; userinfo_endpoint?: string }>>();
function discover(issuer: string) {
  let found = discovered.get(issuer);
  if (!found) {
    found = fetch(issuer.replace(/\/$/, "") + "/.well-known/openid-configuration").then(async r => {
      if (!r.ok) throw new Error("OIDC discovery failed for " + issuer + ": " + r.status);
      return (await r.json()) as { authorization_endpoint: string; token_endpoint: string; userinfo_endpoint?: string };
    });
    discovered.set(issuer, found);
  }
  return found;
}

function providerOrFail(name: string): ProviderConfig {
  const provider = OAUTH[name];
  if (!provider) fail(404, "not_found", "No such provider");
  if (!provider.clientId || !provider.clientSecret) fail(400, "provider_unconfigured", "Set OAUTH_" + name.toUpperCase().replace(/-/g, "_") + "_CLIENT_ID and _CLIENT_SECRET");
  return provider;
}

function redirectUri(name: string): string {
  return APP_URL + "/api/auth/oauth/" + name + "/callback";
}

/** Record the pending authorisation and answer the provider's URL to send the browser to. */
export async function oauthStart(name: string, redirectTo = "/"): Promise<string> {
  const provider = providerOrFail(name);
  const state = randomBytes(24).toString("base64url");
  const verifier = provider.pkce ? randomBytes(32).toString("base64url") : null;
  const nonce = provider.kind === "oidc" ? randomBytes(16).toString("base64url") : null;
  await db.insert(oslAuthStates).values({
    state_hash: hash(state),
    provider: name,
    code_verifier: verifier,
    nonce,
    redirect_to: redirectTo,
    expires_at: new Date(Date.now() + OAUTH_STATE_MINUTES * 60_000)
  });
  const params = new URLSearchParams({ client_id: provider.clientId, redirect_uri: redirectUri(name), scope: provider.scope, state, response_type: "code" });
  if (verifier) {
    params.set("code_challenge", createHash("sha256").update(verifier).digest("base64url"));
    params.set("code_challenge_method", "S256");
  }
  if (nonce) params.set("nonce", nonce);
  const endpoint = provider.kind === "oidc" ? (await discover(provider.issuer)).authorization_endpoint : provider.authorize;
  return endpoint + "?" + params.toString();
}

/**
 * Finish the authorisation: check the state, exchange the code, read the profile, find or create the user. The
 * provider has proven the address it answers, so the invites waiting for it are accepted, and the browser goes to
 * what was joined.
 */
export async function oauthCallback(name: string, params: Record<string, string | undefined>): Promise<{ user: User; redirectTo: string }> {
  const provider = providerOrFail(name);
  if (params.error) fail(400, "oauth_denied", params.error_description ?? params.error);
  if (!params.code || !params.state) fail(400, "oauth_invalid", "Missing code or state");
  const [pending] = await db
    .delete(oslAuthStates)
    .where(and(eq(oslAuthStates.state_hash, hash(params.state)), eq(oslAuthStates.provider, name), gt(oslAuthStates.expires_at, new Date())))
    .returning();
  if (!pending) fail(400, "oauth_invalid", "This sign-in attempt is unknown or has expired");

  const tokenEndpoint = provider.kind === "oidc" ? (await discover(provider.issuer)).token_endpoint : provider.token;
  const form = new URLSearchParams({ grant_type: "authorization_code", code: params.code, redirect_uri: redirectUri(name), client_id: provider.clientId, client_secret: provider.clientSecret });
  if (pending.code_verifier) form.set("code_verifier", pending.code_verifier);
  const tokenResponse = await fetch(tokenEndpoint, { method: "POST", headers: { accept: "application/json", "content-type": "application/x-www-form-urlencoded" }, body: form });
  if (!tokenResponse.ok) fail(400, "oauth_exchange_failed", "The provider refused the code");
  const tokens = (await tokenResponse.json()) as { access_token?: string; id_token?: string };
  if (!tokens.access_token) fail(400, "oauth_exchange_failed", "The provider sent no access token");

  const profile = await fetchProfile(provider, tokens, pending.nonce);
  const [linked] = await db
    .select()
    .from(oslAuthAccounts)
    .where(and(eq(oslAuthAccounts.provider, name), eq(oslAuthAccounts.provider_account_id, profile.id)));
  let user: User;
  if (linked) {
    const found = await db.query.users.findFirst({ where: eq(identityTable.id, linked.user_id) });
    if (!found) fail(400, "oauth_invalid", "The linked account no longer exists");
    user = found;
  } else {
    if (!profile.email) fail(400, "oauth_no_email", "The provider shared no verified email address");
    user = await findOrCreateByEmail(profile.email, profile.name);
    await db.insert(oslAuthAccounts).values({ provider: name, provider_account_id: profile.id, user_id: user.id });
  }
  const accepted = await acceptPending(user, profile.email);
  return { user, redirectTo: accepted.length ? acceptedPath(accepted[0]) : (pending.redirect_to ?? "/") };
}

async function fetchProfile(provider: ProviderConfig, tokens: { access_token?: string; id_token?: string }, nonce: string | null): Promise<{ id: string; email: string | null; name?: string }> {
  const bearer = { authorization: "Bearer " + tokens.access_token, accept: "application/json", "user-agent": "osl" };
  if (provider.kind === "github") {
    const user = (await (await fetch("https://api.github.com/user", { headers: bearer })).json()) as { id: number; email: string | null; name: string | null; login: string };
    let email = user.email;
    if (!email) {
      const emails = (await (await fetch("https://api.github.com/user/emails", { headers: bearer })).json()) as { email: string; primary: boolean; verified: boolean }[];
      email = emails.find(e => e.primary && e.verified)?.email ?? emails.find(e => e.verified)?.email ?? null;
    }
    return { id: String(user.id), email, name: user.name ?? user.login };
  }
  if (tokens.id_token) {
    const claims = JSON.parse(Buffer.from(tokens.id_token.split(".")[1], "base64url").toString()) as { sub: string; email?: string; email_verified?: boolean; name?: string; nonce?: string };
    if (nonce && claims.nonce !== nonce) fail(400, "oauth_invalid", "The identity token does not match this sign-in");
    return { id: claims.sub, email: claims.email_verified === false ? null : (claims.email ?? null), name: claims.name };
  }
  const userinfo = (await discover(provider.issuer)).userinfo_endpoint;
  if (!userinfo) fail(400, "oauth_invalid", "The provider shared no identity");
  const info = (await (await fetch(userinfo, { headers: bearer })).json()) as { sub: string; email?: string; email_verified?: boolean; name?: string };
  return { id: info.sub, email: info.email_verified === false ? null : (info.email ?? null), name: info.name };
}

// Invites. An invite is a row of an invite resource; its link carries a token the row keeps only the hash of.

/** What accepting an invite made: the row joined, the role given in it, and the tenant that row belongs to */
export type Accepted = { entity: string; id: string | number; role?: string; tenant: string | number | null };

/** What an invite shows whoever holds its link, before anyone has proven the address */
export type InviteLookup = {
  entity: string;
  name: string;
  role?: string;
  inviter: string;
  email: string;
  expires_at: string;
  account: boolean;
};

/** The part of a user the invite code reads */
type Invitee = Pick<User, "id" | "email">;

type FoundInvite =
  | { membership: "ArticleEditor"; row: ArticleInvite };

/** Where the browser goes after a sign-in that accepted invites: the page that opens what was joined */
export function acceptedPath(first: Accepted): string {
  const params = new URLSearchParams({ entity: first.entity, id: String(first.id) });
  if (first.tenant !== null) params.set("tenant", String(first.tenant));
  return "/invite/accepted?" + params.toString();
}

function maskEmail(email: string): string {
  const at = email.lastIndexOf("@");
  return at < 1 ? "•••" : email[0] + "•••" + email.slice(at);
}

/** The invite a token belongs to, lapsed or not */
async function inviteOf(token: string): Promise<FoundInvite | null> {
  const tokenHash = hash(token);
  const [articleInvite] = await db.select().from(articleInvites).where(eq(articleInvites.token_hash, tokenHash));
  if (articleInvite) return { membership: "ArticleEditor", row: articleInvite };
  return null;
}

/** The token's invite: 404 for a token that is unknown, used or revoked, 410 for one that has lapsed */
async function liveInvite(token: string): Promise<FoundInvite> {
  const found = await inviteOf(token);
  if (!found) fail(404, "not_found", "Not found");
  if (found.row.expires_at.getTime() <= Date.now()) fail(410, "invite_expired", "This invite has expired");
  return found;
}

async function parentOf(found: FoundInvite): Promise<{ entity: string; name: string; role?: string }> {
  switch (found.membership) {
    case "ArticleEditor": {
      const [parent] = await db.select({ name: articles.title }).from(articles).where(eq(articles.id, found.row.article_id));
      return { entity: "Article", name: String(parent?.name ?? "") };
    }
  }
}

/**
 * Send an invite to a Article. `before` is the resource's beforeCreate hook, handed the row as it will be
 * stored. Then, in order: the role ceiling, 409 for an address already invited or already a member, the row with
 * the token's hash, the mail. The row is kept only if the mail was handed to the adapter. The token is answered
 * only when emails are captured (tests).
 */
export async function issueArticleInvite(
  input: Pick<NewArticleInvite, "article_id" | "email">,
  session: Session,
  before: (values: NewArticleInvite) => Promise<NewArticleInvite> = async values => values
): Promise<{ row: ArticleInvite; debug?: { token: string; url: string } }> {
  const token = randomBytes(32).toString("base64url");
  const me = session.user.id;
  const draft = await before({
    ...input,
    email: input.email.trim().toLowerCase(),
    invited_by: me,
    token_hash: hash(token),
    expires_at: new Date(Date.now() + 604800 * 1000)
  });
  const values = { ...draft, email: draft.email.trim().toLowerCase(), invited_by: me, token_hash: hash(token) };
  const parentId = values.article_id;

  const [waiting] = await db
    .select()
    .from(articleInvites)
    .where(and(eq(articleInvites.article_id, parentId), eq(articleInvites.email, values.email)));
  if (waiting && waiting.expires_at.getTime() > Date.now()) fail(409, "invite_exists", "An invite to this address is already waiting");
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, values.email));
  if (account) {
    const [member] = await db
      .select({ user: articleEditors.user_id })
      .from(articleEditors)
      .where(and(eq(articleEditors.article_id, parentId), eq(articleEditors.user_id, account.id)));
    if (member) fail(409, "already_member", "This address already belongs to a member");
  }
  const [parent] = await db.select({ name: articles.title }).from(articles).where(eq(articles.id, parentId));
  if (!parent) fail(400, "invalid_reference", "A referenced row does not exist");

  // A lapsed invite to the address gives way to the new one
  const row = await db.transaction(async tx => {
    if (waiting) await tx.delete(articleInvites).where(eq(articleInvites.id, waiting.id));
    const [made] = await tx.insert(articleInvites).values(values).returning();
    return made;
  });
  const url = APP_URL + "/invite/" + encodeURIComponent(token);
  try {
    await sendEmail(
      inviteEmail({
        to: row.email,
        name: String(parent.name),
        inviter: String((session.user as Record<string, unknown>)["name"] ?? ""),
        role: null,
        url,
        expires: row.expires_at
      })
    );
  } catch (err) {
    await db.delete(articleInvites).where(eq(articleInvites.id, row.id));
    throw err;
  }
  return emailMode() === "capture" ? { row, debug: { token, url } } : { row };
}

/**
 * Make the ArticleEditor an invite stands for and use the invite up, in one transaction. A membership that
 * exists already is left as it is. Null when the invite was gone before this could take it.
 */
async function acceptArticleInvite(user: Invitee, invite: ArticleInvite): Promise<Accepted | null> {
  const made = await db.transaction(async tx => {
    const [used] = await tx.delete(articleInvites).where(eq(articleInvites.id, invite.id)).returning({ id: articleInvites.id });
    if (!used) return null;
    const [member] = await tx.insert(articleEditors).values({ article_id: invite.article_id, user_id: user.id }).onConflictDoNothing().returning();
    return { member };
  });
  if (!made) return null;
  return { entity: "Article", id: invite.article_id, tenant: null };
}

/**
 * The one place an invite becomes a membership. It does nothing unless the proven email is the account's own; then
 * every live invite to that address is accepted, across all invited memberships. Answers what it accepted: the
 * invite whose token was used first, then the others, oldest first.
 */
export async function acceptPending(user: Invitee, provenEmail: string | null | undefined, usedToken?: string): Promise<Accepted[]> {
  const email = (provenEmail ?? "").trim().toLowerCase();
  if (!email || email !== String(user.email ?? "").trim().toLowerCase()) return [];
  const now = new Date();
  const first = usedToken ? hash(usedToken) : null;
  const done: { accepted: Accepted; first: boolean; at: number }[] = [];
  for (const invite of await db.select().from(articleInvites).where(and(eq(articleInvites.email, email), gt(articleInvites.expires_at, now)))) {
    const accepted = await acceptArticleInvite(user, invite);
    if (accepted) done.push({ accepted, first: invite.token_hash === first, at: invite.created_at.getTime() });
  }
  done.sort((a, b) => Number(b.first) - Number(a.first) || a.at - b.at);
  return done.map(entry => entry.accepted);
}

/** A password proves nothing about a mailbox, so a password sign-in accepts only with a live token for its own address. */
export async function acceptWithToken(user: Invitee, token: string): Promise<Accepted[]> {
  const found = await inviteOf(token);
  if (!found || found.row.expires_at.getTime() <= Date.now()) return [];
  return acceptPending(user, found.row.email, token);
}

/** GET /api/auth/invites/{token}: what the landing page shows. It never accepts, because mail scanners open links. */
export async function lookupInvite(token: string): Promise<InviteLookup> {
  const found = await liveInvite(token);
  const [inviter] = await db.select({ name: identityTable.name }).from(identityTable).where(eq(identityTable.id, found.row.invited_by));
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, found.row.email));
  return {
    ...(await parentOf(found)),
    inviter: String(inviter?.name ?? ""),
    email: maskEmail(found.row.email),
    expires_at: found.row.expires_at.toISOString(),
    account: Boolean(account)
  };
}

/**
 * POST /api/auth/invites/{token}/accept. A session under the invite's email accepts; one under another email is
 * refused, and nothing changes. Without a session the token never signs anyone into an account that exists: it
 * asks for a sign-in. Where the address has no account, `create` makes it (the token has proven the address), and
 * the caller signs it in.
 */
export async function acceptInvite(
  token: string,
  userId: User["id"] | null,
  create: (email: string) => Promise<User>
): Promise<{ accepted: Accepted[]; created: User | null }> {
  const found = await liveInvite(token);
  const email = found.row.email;
  if (userId !== null) {
    const [me] = await db.select().from(identityTable).where(eq(identityTable.id, userId));
    if (!me || String(me.email ?? "").trim().toLowerCase() !== email) fail(403, "invite_email_mismatch", "This invite is for another address");
    return { accepted: await acceptPending(me, email, token), created: null };
  }
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, email));
  if (account) fail(401, "sign_in_required", "Sign in to accept this invite");
  const created = await create(email);
  return { accepted: await acceptPending(created, email, token), created };
}
